let page='skills', chosen='foundation', routine='beginner', filter='all';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let sessions=read('momentum_sessions',[]), sets=read('momentum_sets',{});if(!Array.isArray(sessions))sessions=[];if(!sets||typeof sets!=='object'||Array.isArray(sets))sets={};
let watchStart=0,watchElapsed=0,watchRunning=false,laps=[],restEnd=0;
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{document.querySelector('#notice').textContent='Browser storage unavailable; changes last for this session.'}};
const fmt=ms=>{const t=Math.floor(ms/1000);return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`};
const elapsed=()=>watchElapsed+(watchRunning?Date.now()-watchStart:0);
const done=s=>s.steps.filter(x=>completedSteps.includes(x.id)).length;
const total=()=>Object.values(SKILLS_DATA).reduce((n,s)=>n+done(s),0);
function go(next){page=next;render()}
function choose(id){chosen=id;render()}
function progress(id){completedSteps=completedSteps.includes(id)?completedSteps.filter(x=>x!==id):[...completedSteps,id];save('momentum_completed_steps',completedSteps);render()}
function setDone(index,set){const key=`${routine}:${index}:${set}`;sets[key]=!sets[key];save('momentum_sets',sets);render()}
function watch(action){if(action==='toggle'){if(watchRunning){watchElapsed=elapsed();watchRunning=false}else{watchStart=Date.now();watchRunning=true}}if(action==='reset'){watchElapsed=0;watchRunning=false;laps=[]}if(action==='lap'&&elapsed()>0)laps.unshift(fmt(elapsed()));render()}
function rest(seconds){restEnd=seconds?Date.now()+seconds*1000:0;tick()}
function finish(){const r=ROUTINES_DATA[routine];const count=r.exercises.reduce((n,e,i)=>n+Array.from({length:parseInt(e.sets)||1},(_,j)=>!!sets[`${routine}:${i}:${j}`]).filter(Boolean).length,0);if(!count)return;sessions.unshift({title:r.title,date:new Date().toISOString(),sets:count});Object.keys(sets).filter(k=>k.startsWith(routine+':')).forEach(k=>delete sets[k]);save('momentum_sessions',sessions);save('momentum_sets',sets);page='history';render()}
function tick(){const w=document.querySelector('#watch');if(w)w.textContent=fmt(elapsed());const r=document.querySelector('#rest');if(r)r.textContent=restEnd?(Date.now()>=restEnd?'Ready!':fmt(Math.ceil((restEnd-Date.now())/1000)*1000)):'01:00'}
function toolsPanel(){return `<aside class="tools"><section class="panel"><span class="eyebrow">Training tools</span><h3 style="margin-top:12px">Skill stopwatch</h3><p>Time your holds and attempts.</p><div class="clock" id="watch">${fmt(elapsed())}</div><div class="buttons"><button class="primary" onclick="watch('toggle')">${watchRunning?'Pause':'Start'}</button><button onclick="watch('lap')">Lap</button><button onclick="watch('reset')">Reset</button></div>${laps.slice(0,5).map((l,i)=>`<div class="lap"><span>Lap ${laps.length-i}</span><span>${l}</span></div>`).join('')}</section><section class="panel"><h3>Rest & recover</h3><p>Take a breath between sets.</p><div class="clock" id="rest" role="timer">01:00</div><div class="buttons"><button onclick="rest(45)">45s</button><button onclick="rest(60)">60s</button><button onclick="rest(90)">90s</button><button onclick="rest(0)">Reset</button></div></section><section class="panel"><h3>One step at a time</h3><p>Mark a progression complete when you can repeat it with control. Your progress is saved on this browser.</p></section></aside>`}
function skillsView(){const s=SKILLS_DATA[chosen];return `<div class="section-head"><div><h2>Your skill library</h2><p>Find your starting point. Build from there.</p></div><div class="filter">${['all','beginner','intermediate','advanced'].map(f=>`<button class="${filter===f?'selected':''}" onclick="filter='${f}';render()">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div></div><div class="cards">${['foundation','kipup','handstand','muscleup'].filter(id=>filter==='all'||SKILLS_DATA[id].difficulty.toLowerCase().includes(filter)).map(id=>{const k=SKILLS_DATA[id];return `<button class="skill ${chosen===id?'active':''}" onclick="choose('${id}')" aria-pressed="${chosen===id}"><span class="icon">${k.icon}</span><h3>${k.title}</h3><small>${k.difficulty} · ${done(k)}/${k.steps.length} complete</small><div class="bar"><span style="width:${done(k)/k.steps.length*100}%"></span></div></button>`}).join('')}</div><div class="workspace"><section class="panel"><span class="eyebrow">Your progression roadmap</span><h2 style="margin-top:12px">${s.title}</h2><p>${s.tagline}</p><p style="font-size:12px;margin-bottom:20px">Foundations: ${s.prerequisites.join(' · ')}</p>${s.steps.map(step=>`<label class="step ${completedSteps.includes(step.id)?'done':''}"><input type="checkbox" onchange="progress('${step.id}')" ${completedSteps.includes(step.id)?'checked':''}><div><h3>${step.title}</h3><p>${step.cue}</p><p style="margin-top:8px"><strong>Watch out:</strong> ${step.pitfall}</p><span class="target">${step.reps}</span></div></label>`).join('')}</section>${toolsPanel()}</div>`}
function workoutView(){const r=ROUTINES_DATA[routine];return `<div class="section-head"><div><h2>Make today count</h2><p>Choose a session and tap each set as you finish.</p></div></div><div class="tabs">${Object.keys(ROUTINES_DATA).map(id=>`<button class="${routine===id?'selected':''}" onclick="routine='${id}';render()">${({beginner:'Foundations',skill_day:'Skill practice',push_pull:'Push / Pull',core_flex:'Core & mobility'})[id]}</button>`).join('')}</div><div class="workspace"><section class="panel"><span class="eyebrow">${r.duration} · Training session</span><h2 style="margin-top:12px">${r.title}</h2><p>${r.desc}</p>${r.exercises.map((e,i)=>`<div class="exercise"><h3>${i+1}. ${e.name}</h3><p>${e.note}</p><small>${e.sets} · ${e.target}</small><div class="set-buttons">${Array.from({length:parseInt(e.sets)||1},(_,j)=>`<button aria-pressed="${!!sets[`${routine}:${i}:${j}`]}" class="${sets[`${routine}:${i}:${j}`]?'selected':''}" onclick="setDone(${i},${j})">${sets[`${routine}:${i}:${j}`]?'✓ ':''}Set ${j+1}</button>`).join('')}</div></div>`).join('')}<button class="primary" onclick="finish()" ${Object.keys(sets).some(k=>k.startsWith(routine+':')&&sets[k])?'':'disabled'}>Save completed sets</button><p style="font-size:12px;margin-top:10px">Logs this session and clears its set checkmarks.</p></section>${toolsPanel()}</div>`}
function historyView(){return `<div class="workspace"><section class="panel"><h2>Your training journal</h2><p>Every session is a step forward.</p><div class="history">${sessions.length?sessions.map(s=>`<div class="history-row"><div><h3>${escapeText(s.title)}</h3><p>${new Date(s.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</p></div><span>${Number(s.sets)||0} sets completed</span></div>`).join(''):'<div class="empty"><h3>Your first session starts here</h3><p>Complete sets in Workouts, then save your session.</p><button class="primary" style="margin-top:20px" onclick="go(\'workouts\')">Explore workouts →</button></div>'}</div></section>${toolsPanel()}</div>`}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c])}
function render(){const mastered=Object.values(SKILLS_DATA).filter(s=>done(s)===s.steps.length).length;document.body.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">M</span>Momentum</div><nav aria-label="Main navigation">${[['skills','↗','Skill library'],['workouts','▦','Workouts'],['history','◷','My progress']].map(([id,icon,title])=>`<button class="${page===id?'selected':''}" onclick="go('${id}')" ${page===id?'aria-current="page"':''}>${icon} &nbsp; ${title}</button>`).join('')}</nav><div class="side-note"><span class="eyebrow">The long game</span><p style="margin-top:10px">Consistency builds strength.<br>Show up for your next step.</p></div></aside><main class="content"><div class="topline"><span class="eyebrow">Your training space</span><small>● &nbsp; Saved on this device</small></div><section class="hero"><div><span class="eyebrow">Build strength. Find your balance.</span><h1 style="margin-top:12px">A little stronger.<br>Every single session.</h1><p>Learn the skills. Put in the practice. Turn small wins into lasting Momentum.</p></div><div class="hero-symbol" aria-hidden="true">↗</div></section><section class="stats" aria-label="Progress summary"><div class="stat"><small>PROGRESSION STEPS</small><strong>${total()}<span style="font-size:15px;color:var(--muted)"> / 16</span></strong><small>Your foundation for the next skill</small></div><div class="stat"><small>SKILLS COMPLETED</small><strong>${mastered}<span style="font-size:15px;color:var(--muted)"> / 4</span></strong><small>Keep building your skill library</small></div><div class="stat"><small>SESSIONS LOGGED</small><strong>${sessions.length}</strong><small>${sessions.reduce((n,s)=>n+(Number(s.sets)||0),0)} total sets completed</small></div></section>${page==='skills'?skillsView():page==='workouts'?workoutView():historyView()}<p class="notice" id="notice" role="status"></p></main></div>`;tick()}
window.onload=()=>{render();setInterval(tick,150)};
